    public static List<List<GenericStack>> ofInputs(IRecipeSlotsView recipeLayout) {
        return recipeLayout.getSlotViews(RecipeIngredientRole.INPUT).stream().map(GenericEntryStackHelper::ofSlot).toList();
    }

    public static List<GenericStack> ofOutputs(IRecipeSlotsView recipeLayout) {
        return recipeLayout.getSlotViews(RecipeIngredientRole.OUTPUT).stream().flatMap(slot -> GenericEntryStackHelper.ofSlot(slot).stream().limit(1L)).toList();
    }

    private static List<GenericStack> ofSlot(IRecipeSlotView slot) {
        return slot.getAllIngredients().map(GenericEntryStackHelper::ingredientToStack).filter(Objects::nonNull).toList();
    }

    @Nullable
    private static <T> GenericStack tryConvertToStack(IngredientConverter<T> converter, Object ingredient) {
        Class ingredientClass = converter.getIngredientType().getIngredientClass();
        if (ingredientClass.isInstance(ingredient)) {
            return converter.getStackFromIngredient(ingredientClass.cast(ingredient));
        }
        return null;
    }

    @Nullable
    private static <T, U> GenericStack tryConvertTypedToStack(IngredientConverter<T> converter, IIngredientType<U> ingredientType, U ingredient) {
        if (converter.getIngredientType().equals(ingredientType)) {
            return converter.getIngredientType().castIngredient(ingredient).map(converter::getStackFromIngredient).orElse(null);
        }
        return null;
    }
}

